import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    iterator = iter(input_data)

    try:
        n = int(next(iterator))
        m = int(next(iterator))
        k = int(next(iterator))
    except StopIteration:
        return

    grid = []
    for _ in range(n):
        grid.append(next(iterator))

    visited = [[False] * m for _ in range(n)]
    component_pictures = {}
    component_id = 0

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.' and not visited[r][c]:
                q = deque()
                q.append((r, c))
                visited[r][c] = True
                pictures = 0

                while q:
                    cr, cc = q.popleft()

                    for dr, dc in directions:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if grid[nr][nc] == '*':
                                pictures += 1
                            elif grid[nr][nc] == '.' and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))

                component_id += 1
                component_pictures[(r, c)] = pictures

    results = []
    for _ in range(k):
        x = int(next(iterator))
        y = int(next(iterator))
        r, c = x - 1, y - 1

        if grid[r][c] == '.':
            results.append(component_pictures.get((r, c), 0))
        else:
            results.append(0)

    print('\n'.join(map(str, results)))

if __name__ == "__main__":
    main()
